shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #eae3d5;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-dark: #c8c1b1;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.12);
    --crimson: #9e2a2b;
    --navy-bg: #0f1d2b;
    --navy-card: #16283a;
    --navy-line: #283e54;
    --mono-green: #2c6e49;

    --font-serif-cn: 'Noto Serif SC', serif;
    --font-sans-cn: 'Noto Sans SC', sans-serif;
    --font-serif-en: 'Lora', serif;
    --font-display: 'Playfair Display', 'Noto Serif SC', serif;
    --font-sans: 'Inter', 'Noto Sans SC', sans-serif;
    --font-mono: 'JetBrains Mono', 'Noto Sans SC', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    scroll-behavior: smooth;
    -webkit-font-smoothing: antialiased;
  }

  /* Strict Bilingual Toggle Rules */
  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  .wsj-shadow-body {
    font-family: var(--font-serif-cn);
    background-color: var(--paper);
    overflow-x: hidden;
    line-height: 1.8;
  }

  :host([lang="en"]) .wsj-shadow-body {
    font-family: var(--font-serif-en);
    line-height: 1.72;
  }

  /* Reading Progress Bar */
  .progress-bar {
    position: fixed;
    top: 0;
    left: 0;
    height: 3px;
    background: var(--accent);
    width: 0%;
    z-index: 1001;
    transition: width 0.1s ease-out;
  }

  /* Sticky Top Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 1000;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--line);
    padding: 0.75rem 1.5rem;
  }

  .masthead-inner {
    max-width: 1240px;
    margin: 0 auto;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
  }

  .brand-group {
    display: flex;
    align-items: center;
    gap: 0.85rem;
    flex-wrap: wrap;
  }

  .wsj-mark {
    font-family: var(--font-display);
    font-weight: 800;
    font-size: 0.95rem;
    letter-spacing: 0.08em;
    color: var(--ink);
    text-transform: uppercase;
  }

  .brand-divider {
    width: 1px;
    height: 14px;
    background: var(--line-dark);
  }

  .desk-badge {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
    font-weight: 600;
  }

  .lang-switch {
    display: inline-flex;
    background: var(--paper-card);
    border: 1px solid var(--line-dark);
    border-radius: 999px;
    padding: 2px;
    flex-shrink: 0;
  }

  .lang-btn {
    border: none;
    background: transparent;
    font-family: var(--font-sans);
    font-size: 0.75rem;
    font-weight: 600;
    padding: 0.3rem 0.75rem;
    border-radius: 999px;
    cursor: pointer;
    color: var(--muted);
    transition: all 0.2s ease;
  }

  :host([lang="zh-CN"]) .lang-btn[data-lang="zh-CN"],
  :host([lang="en"]) .lang-btn[data-lang="en"] {
    background: var(--ink);
    color: var(--paper);
  }

  /* Hero Section */
  .hero {
    max-width: 1240px;
    margin: 0 auto;
    padding: 3.5rem 1.5rem 2.5rem;
    border-bottom: 1px solid var(--line);
  }

  .hero-kicker {
    display: inline-flex;
    align-items: center;
    gap: 0.6rem;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    letter-spacing: 0.1em;
    text-transform: uppercase;
    color: var(--crimson);
    margin-bottom: 1.25rem;
    font-weight: 700;
  }

  .live-dot {
    width: 8px;
    height: 8px;
    border-radius: 50%;
    background: var(--crimson);
    box-shadow: 0 0 0 4px rgba(158, 42, 43, 0.2);
  }

  .hero-title {
    font-family: var(--font-display);
    font-size: clamp(2.1rem, 4.4vw, 3.6rem);
    line-height: 1.16;
    font-weight: 800;
    color: var(--ink);
    letter-spacing: -0.015em;
    max-width: 960px;
    margin-bottom: 1.25rem;
  }

  .hero-dek {
    font-family: var(--font-serif-cn);
    font-size: clamp(1.15rem, 2vw, 1.45rem);
    line-height: 1.55;
    color: var(--muted);
    max-width: 820px;
    font-weight: 400;
    margin-bottom: 2rem;
  }

  :host([lang="en"]) .hero-dek {
    font-family: var(--font-serif-en);
  }

  .byline-bar {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    justify-content: space-between;
    gap: 1rem;
    padding-top: 1.25rem;
    border-top: 1px solid var(--line);
    font-family: var(--font-sans);
    font-size: 0.85rem;
    color: var(--muted);
  }

  .byline-authors strong {
    color: var(--ink);
    font-weight: 600;
  }

  .byline-meta {
    font-family: var(--font-mono);
    font-size: 0.78rem;
    color: var(--muted);
  }

  /* Global Attack Surface Telemetry Strip */
  .telemetry-strip {
    max-width: 1240px;
    margin: 2rem auto 0;
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    background: var(--navy-bg);
    color: #f8f6f0;
    border-radius: 4px;
    overflow: hidden;
    border: 1px solid var(--navy-line);
  }

  .telemetry-cell {
    padding: 1.35rem 1.5rem;
    border-right: 1px solid var(--navy-line);
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }

  .telemetry-cell:last-child {
    border-right: none;
  }

  .telemetry-tag {
    font-family: var(--font-mono);
    font-size: 0.68rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #90a4b8;
    margin-bottom: 0.4rem;
  }

  .telemetry-num {
    font-family: var(--font-display);
    font-size: 2rem;
    font-weight: 700;
    color: #f3a86c;
    line-height: 1.1;
    margin-bottom: 0.45rem;
  }

  .telemetry-desc {
    font-family: var(--font-sans);
    font-size: 0.8rem;
    line-height: 1.45;
    color: #cbd5e1;
  }

  /* Context Dossier Banner */
  .dossier-container {
    max-width: 1240px;
    margin: 2rem auto 0;
    padding: 0 1.5rem;
  }

  .dossier-box {
    background: var(--paper-card);
    border: 1px solid var(--line-dark);
    border-left: 4px solid var(--ink);
    padding: 1.35rem 1.75rem;
    display: grid;
    grid-template-columns: 200px 1fr;
    gap: 1.5rem;
    align-items: start;
  }

  .dossier-label {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--ink);
  }

  .dossier-label span {
    display: block;
    font-size: 0.68rem;
    color: var(--muted);
    font-weight: 400;
    margin-top: 0.25rem;
  }

  .dossier-text {
    font-family: var(--font-sans);
    font-size: 0.92rem;
    line-height: 1.68;
    color: var(--body);
  }

  /* Main Asymmetric Editorial Layout */
  .editorial-stage {
    max-width: 1240px;
    margin: 0 auto;
    padding: 3rem 1.5rem 5rem;
  }

  .chapter-grid {
    display: grid;
    grid-template-columns: minmax(0, 680px) minmax(280px, 420px);
    justify-content: space-between;
    gap: 3.5rem;
    align-items: start;
    margin-bottom: 3.5rem;
  }

  .prose-column {
    width: 100%;
  }

  .rail-column {
    position: sticky;
    top: 4.75rem;
    display: flex;
    flex-direction: column;
    gap: 1.75rem;
  }

  /* Prose Styling */
  .prose-p {
    font-size: 1.125rem;
    color: var(--body);
    margin-bottom: 1.45rem;
    letter-spacing: 0.01em;
  }

  :host([lang="en"]) .prose-p {
    font-size: 1.1rem;
    letter-spacing: 0;
  }

  /* Lead Paragraph Styling (No ::first-letter on Chinese) */
  .lead-p {
    font-size: 1.24rem;
    font-weight: 600;
    color: var(--ink);
    border-left: 3px solid var(--accent);
    padding-left: 1.15rem;
    margin-bottom: 1.65rem;
    line-height: 1.75;
  }

  /* Source Subheadings */
  .source-subhead {
    font-family: var(--font-display);
    font-size: 1.75rem;
    font-weight: 700;
    color: var(--ink);
    margin: 2.75rem 0 1.35rem;
    padding-top: 1.75rem;
    border-top: 2px solid var(--ink);
    letter-spacing: -0.01em;
    display: flex;
    align-items: baseline;
    gap: 0.75rem;
  }

  .source-subhead::before {
    content: "§";
    font-family: var(--font-mono);
    font-size: 1.1rem;
    color: var(--accent);
    font-weight: 500;
  }

  /* Inline Highlighting */
  mark.ed-hl {
    background: linear-gradient(120deg, rgba(184, 93, 25, 0.16) 0%, rgba(184, 93, 25, 0.24) 100%);
    color: var(--ink);
    padding: 0.08em 0.28em;
    border-radius: 2px;
    border-bottom: 1.5px solid var(--accent);
    font-weight: 500;
  }

  /* Derived Pull Quote Cards */
  .pull-quote {
    background: var(--paper-card);
    border-top: 3px solid var(--accent);
    border-bottom: 1px solid var(--line-dark);
    padding: 1.5rem 1.4rem;
  }

  .quote-text {
    font-family: var(--font-display);
    font-size: 1.18rem;
    line-height: 1.55;
    color: var(--ink);
    font-weight: 700;
    margin-bottom: 0.85rem;
  }

  .quote-attrib {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }

  /* Forensic SVG & Dossier Cards */
  .forensic-card {
    background: var(--paper-card);
    border: 1px solid var(--line-dark);
    padding: 1.4rem;
    border-radius: 2px;
  }

  .forensic-card.dark-theme {
    background: var(--navy-bg);
    border-color: var(--navy-line);
    color: #f4f1ea;
  }

  .card-kicker {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    margin-bottom: 0.4rem;
    font-weight: 700;
    display: flex;
    align-items: center;
    justify-content: space-between;
  }

  .dark-theme .card-kicker {
    color: #f3a86c;
  }

  .card-title {
    font-family: var(--font-sans);
    font-size: 1.02rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 0.65rem;
    line-height: 1.35;
  }

  .dark-theme .card-title {
    color: #ffffff;
  }

  .card-caption {
    font-family: var(--font-sans);
    font-size: 0.8rem;
    line-height: 1.55;
    color: var(--muted);
    margin-top: 0.85rem;
    padding-top: 0.75rem;
    border-top: 1px solid var(--line);
  }

  .dark-theme .card-caption {
    color: #9fb1c4;
    border-top-color: var(--navy-line);
  }

  /* Full-Bleed Breakout Visuals between Chapters */
  .breakout-panel {
    margin: 2.5rem 0 3.5rem;
    background: var(--paper-card);
    border-top: 2px solid var(--ink);
    border-bottom: 1px solid var(--line-dark);
    padding: 2rem;
  }

  .breakout-header {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: flex-end;
    gap: 1rem;
    margin-bottom: 1.75rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid var(--line-dark);
  }

  .breakout-title {
    font-family: var(--font-display);
    font-size: 1.45rem;
    font-weight: 700;
    color: var(--ink);
  }

  .breakout-sub {
    font-family: var(--font-sans);
    font-size: 0.88rem;
    color: var(--muted);
    margin-top: 0.25rem;
  }

  /* Theater Comparison Matrix */
  .theater-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 1.25rem;
  }

  .theater-col {
    background: var(--paper);
    border: 1px solid var(--line-dark);
    padding: 1.25rem;
    display: flex;
    flex-direction: column;
    gap: 0.85rem;
  }

  .theater-badge {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--paper);
    background: var(--ink);
    padding: 0.22rem 0.55rem;
    align-self: flex-start;
  }

  .theater-badge.alert {
    background: var(--crimson);
  }

  .theater-badge.amber {
    background: var(--accent);
  }

  .theater-col h4 {
    font-family: var(--font-sans);
    font-size: 1rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.35;
  }

  .theater-list {
    list-style: none;
    display: flex;
    flex-direction: column;
    gap: 0.65rem;
    font-family: var(--font-sans);
    font-size: 0.84rem;
    line-height: 1.5;
    color: var(--body);
  }

  .theater-list li {
    padding-left: 0.9rem;
    position: relative;
  }

  .theater-list li::before {
    content: "▪";
    position: absolute;
    left: 0;
    color: var(--accent);
  }

  /* Intercepted Transcript Callout for p35 */
  .intercept-box {
    margin: 1.75rem 0;
    background: var(--navy-bg);
    color: #f4f1ea;
    border-left: 4px solid #f3a86c;
    padding: 1.5rem 1.65rem;
    border-radius: 2px;
  }

  .intercept-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #f3a86c;
    margin-bottom: 1rem;
    padding-bottom: 0.65rem;
    border-bottom: 1px solid var(--navy-line);
  }

  .intercept-box .prose-p {
    color: #f4f1ea;
    margin-bottom: 0;
    font-size: 1.06rem;
  }

  /* Climactic Verdict Box for p38 */
  .verdict-panel {
    margin-top: 2rem;
    background: var(--paper-card);
    border: 2px solid var(--ink);
    padding: 2rem 2.25rem;
    position: relative;
  }

  .verdict-tag {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    margin-bottom: 0.75rem;
  }

  .verdict-panel .prose-p {
    font-family: var(--font-display);
    font-size: 1.35rem;
    line-height: 1.55;
    color: var(--ink);
    font-weight: 700;
    margin-bottom: 0;
  }

  /* Footer */
  .ed-footer {
    border-top: 1px solid var(--line-dark);
    background: var(--paper-card);
    padding: 2.5rem 1.5rem;
    font-family: var(--font-sans);
    font-size: 0.8rem;
    color: var(--muted);
  }

  .ed-footer-inner {
    max-width: 1240px;
    margin: 0 auto;
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    gap: 1rem;
  }

  svg {
    display: block;
    width: 100%;
    height: auto;
  }

  /* Responsive Reflow */
  @media (max-width: 980px) {
    .telemetry-strip {
      grid-template-columns: repeat(2, 1fr);
    }
    .telemetry-cell:nth-child(2) {
      border-right: none;
    }
    .telemetry-cell:nth-child(1),
    .telemetry-cell:nth-child(2) {
      border-bottom: 1px solid var(--navy-line);
    }
    .dossier-box {
      grid-template-columns: 1fr;
      gap: 0.65rem;
    }
    .chapter-grid {
      grid-template-columns: 1fr;
      gap: 2rem;
    }
    .rail-column {
      position: static;
    }
    .theater-grid {
      grid-template-columns: 1fr;
    }
  }

  @media (max-width: 560px) {
    .masthead {
      padding: 0.65rem 1rem;
    }
    .hero {
      padding: 2.25rem 1rem 1.75rem;
    }
    .telemetry-strip {
      grid-template-columns: 1fr;
      margin: 1.25rem 1rem 0;
    }
    .telemetry-cell {
      border-right: none !important;
      border-bottom: 1px solid var(--navy-line);
      padding: 1.1rem 1.25rem;
    }
    .telemetry-cell:last-child {
      border-bottom: none;
    }
    .dossier-container {
      padding: 0 1rem;
    }
    .dossier-box {
      padding: 1.15rem;
    }
    .editorial-stage {
      padding: 2rem 1rem 3.5rem;
    }
    .breakout-panel {
      padding: 1.35rem 1.1rem;
    }
    .verdict-panel {
      padding: 1.4rem 1.25rem;
    }
    .verdict-panel .prose-p {
      font-size: 1.15rem;
    }
  }
